/// Read file tool
pub struct ReadFileTool;

impl ReadFileTool {
    pub fn new() -> Arc<Self> {
        Arc::new(Self)
    }
}

impl Default for ReadFileTool {
    fn default() -> Self {
        Self
    }
}

#[async_trait]
impl Tool for ReadFileTool {
    fn name(&self) -> &str {
        "read_file"
    }

    fn description(&self) -> &str {
        "Read the contents of a file from the filesystem."
    }

    fn input_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "path": {
                    "type": "string",
                    "description": "Path to the file to read"
                },
                "encoding": {
                    "type": "string",
                    "default": "utf-8",
                    "description": "File encoding"
                }
            },
            "required": ["path"]
        })
    }

    fn category(&self) -> &str {
        "filesystem"
    }

    fn tags(&self) -> Vec<String> {
        vec!["filesystem".to_string(), "read".to_string(), "file".to_string()]
    }

    async fn execute(&self, input: Value) -> Result<Value> {
        let path = input
            .get("path")
            .and_then(|v| v.as_str())
            .ok_or_else(|| anyhow::anyhow!("Missing required field: path"))?;

        // Security check - prevent reading sensitive files
        let forbidden_paths = ["/etc/shadow", "/etc/sudoers"];
        if forbidden_paths.iter().any(|&p| path.starts_with(p)) {
            return Ok(json!({
                "success": false,
                "error": "Access denied: Cannot read sensitive system files"
            }));
        }

        match tokio::fs::read_to_string(path).await {
            Ok(content) => Ok(json!({
                "success": true,
                "path": path,
                "content": content,
                "size": content.len()
            })),
            Err(e) => Ok(json!({
                "success": false,
                "path": path,
                "error": e.to_string()
            })),
        }
    }
}

/// Write file tool
pub struct WriteFileTool;

impl WriteFileTool {
    pub fn new() -> Arc<Self> {
        Arc::new(Self)
    }
}

impl Default for WriteFileTool {
    fn default() -> Self {
        Self
    }
}

#[async_trait]
impl Tool for WriteFileTool {
    fn name(&self) -> &str {
        "write_file"
    }

    fn description(&self) -> &str {
        "Write content to a file on the filesystem."
    }

    fn input_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "path": {
                    "type": "string",
                    "description": "Path to the file to write"
                },
                "content": {
                    "type": "string",
                    "description": "Content to write to the file"
                },
                "create_dirs": {
                    "type": "boolean",
                    "default": false,
                    "description": "Create parent directories if they don't exist"
                }
            },
            "required": ["path", "content"]
        })
    }

    fn category(&self) -> &str {
        "filesystem"
    }

    fn tags(&self) -> Vec<String> {
        vec!["filesystem".to_string(), "write".to_string(), "file".to_string()]
    }

    async fn execute(&self, input: Value) -> Result<Value> {
        let path = input
            .get("path")
            .and_then(|v| v.as_str())
            .ok_or_else(|| anyhow::anyhow!("Missing required field: path"))?;

        let content = input
            .get("content")
            .and_then(|v| v.as_str())
            .ok_or_else(|| anyhow::anyhow!("Missing required field: content"))?;

        let create_dirs = input
            .get("create_dirs")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);

        // Security check - prevent writing to sensitive locations
        let forbidden_prefixes = ["/etc/", "/boot/", "/sys/", "/proc/"];
        if forbidden_prefixes.iter().any(|&p| path.starts_with(p)) {
            return Ok(json!({
                "success": false,
                "error": "Access denied: Cannot write to system directories"
            }));
        }

        if create_dirs {
            if let Some(parent) = std::path::Path::new(path).parent() {
                tokio::fs::create_dir_all(parent).await?;
            }
        }

        match tokio::fs::write(path, content).await {
            Ok(_) => Ok(json!({
                "success": true,
                "path": path,
                "bytes_written": content.len()
            })),
            Err(e) => Ok(json!({
                "success": false,
                "path": path,
                "error": e.to_string()
            })),
        }
    }
}

