                "is_dir": metadata.is_dir(),
                "is_file": metadata.is_file(),
                "size": metadata.len(),
            }));
        }

        Ok(json!({
            "success": true,
            "path": path,
            "entries": entries,
            "count": entries.len()
        }))
    }
}

