        // Simulated streaming
        let mut sequence = 0u32;

        on_chunk(StreamChunk {
            content: format!("Starting {} {}...\n", agent_id, operation),
            stream_type: StreamType::Progress,
            sequence,
            is_final: false,
            timestamp: Instant::now(),
        });
        sequence += 1;

        // Simulate some work
        tokio::time::sleep(Duration::from_millis(100)).await;

        on_chunk(StreamChunk {
